scwin.isDate = function(dd, tm) {
    try {
        var y, m, d, h, mi, s = "";
        if (dd.length != 8) {
            return false;
        } else {
            y = dd.substr(0, 4);
            m = dd.substr(4, 2);
            d = dd.substr(6, 2);
        }
        if (tm == "") {
            h = "00";
            mi = "00";
            s = "00";
        } else {
            if (tm.length != 4) {
                return false;
            } else {
                h = tm.substr(0, 2);
                mi = tm.substr(2, 2);
                s = "00";
            }
        }
        if (Number(mi) >= 60) {
            return false;
        }
        var date = new Date(y, m - 1, d, h, mi, s, 0);
        //alert(y + "_" + m + "_" + d + "_" + h + "_" + mi + "_" + s);
        if (y == date.getFullYear() && m - 1 == date.getMonth() && d == date.getDate()) {
            return date;
        } else {
            return false;
        }
    } catch (e) {
        return false;
    }
};
scwin.fn_Control1 = function() {
