scwin.fn_validCheck = function() {
    if ($c.stf.getObjectValue(txb_isur_cd) == '') {
        $c.win.alert("[회사코드]를 입력하세요.");
        txb_isur_cd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_COMITE_DD) == '') {
        $c.win.alert("[위원회 일시]를 입력하세요.");
        edt_COMITE_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COMITE_SEQ) != '' && !$c.ut.isNum($c.stf.getObjectValue(txb_COMITE_SEQ))) {
        $c.win.alert("숫자만 입력가능합니다.");
        txb_COMITE_SEQ.focus();
        return false;
    }
    if (!$c.ut.isDate($c.stf.getObjectValue(edt_COMITE_DD), '')) {
        $c.win.alert("[위원회 일시]를 확인해 주세요.");
        edt_COMITE_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_NFAITHDISCLS_DESIGN_DD) != '' && !$c.ut.isDate($c.stf.getObjectValue(edt_NFAITHDISCLS_DESIGN_DD), '')) {
        $c.win.alert("[지정여부 일자]를 확인해 주세요.");
        edt_NFAITHDISCLS_DESIGN_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRD_HALT_DD) != '' && !$c.ut.isDate($c.stf.getObjectValue(edt_TRD_HALT_DD), '')) {
        $c.win.alert("[매매거래정지 일자]를 확인해 주세요.");
        edt_TRD_HALT_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_NFAITHDISCLS_REAL_INVSTG_DD) != '' && !$c.ut.isDate($c.stf.getObjectValue(edt_NFAITHDISCLS_REAL_INVSTG_DD), '')) {
        $c.win.alert("[실질심사 일자]를 확인해 주세요.");
        edt_NFAITHDISCLS_REAL_INVSTG_DD.focus();
        return false;
    }
    if (!scwin.fn_checkNumber(txb_DELIB_BAS_PNLT)) return false;
    if (!scwin.fn_checkNumber(txb_WT_PNLT)) return false;
    if (!scwin.fn_checkNumber(txb_REDU_PNLT)) return false;
    if (!scwin.fn_checkNumber(txb_IMPOST_PNLT)) return false;
    if (!scwin.fn_checkNumber(txb_ACC_PNLT)) return false;
    if (!scwin.fn_checkNumber(txb_DISCLS_VIOL_SANCTN_AMT)) return false;
    return true;
};
scwin.fn_checkNumber = function(obj) {
    if ($c.stf.getObjectValue(obj) != '' && scwin.isNumJum($c.stf.getObjectValue(obj)) == false) {
        $c.win.alert("숫자만 입력가능합니다.");
